ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_panic_days_2"] = {
{"fw_ld7_pcb_0034","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Stop shaking the table!",2,"I'm not shaking the table!",1,"Then why's it- oh my God, oh God, that's the floor, the floor is shaking!",2,"It's something heavy going past, it's just passing, it's just passing"}},
{"fw_ld7_pcb_0035","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"I want somebody in charge, I want a name, I want a face!",2,"There isn't one",1,"There's ALWAYS one, somebody's always in charge!",2,"Then go find 'em and tell 'em we said hi"}},
{"fw_ld7_pcb_0036","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Did you see that? Something just ran by out there!",2,"A deer?",1,"It wasn't a deer, deer don't have shoes!",2,"I just want my own bed, I just want my own bed"}},
{"fw_ld7_pcb_0037","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=calm",{1,"Okay, here's what we do, we stay quiet till it's light",2,"And then?",1,"Then we look, and we make another plan",2,"That's the worst plan I've ever heard, and I'm in, I'm all in"}},
{"fw_ld7_pcb_0038","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Let me out, let me OUT, I can't be shut up like this!",2,"You can't go out there!",1,"I'll go crazy, I'll go crazy shut up with everybody breathing on me!",2,"Then breathe with us, I know, I know, it's too many people, I feel it too"}},
{"fw_ld7_pcb_0039","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"We shouldn't have left Dad's truck",2,"We couldn't carry him",1,"I know, I KNOW, I just keep seeing his hat on the seat",2,"He'd have wanted us to go, he'd have yelled at us for staying"}},
{"fw_ld7_pcb_0040","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I heard a baby, there's a baby somewhere out there",2,"It's a cat",1,"It's a baby! I know a baby when I hear one!",2,"Then we can't help it, we can't, you KNOW we can't"}},
{"fw_ld7_pcb_0041","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Say something, anything, I can't stand the quiet",2,"Like what?",1,"Like what you had for lunch last Sunday",2,"Meatloaf, with the ketchup glaze, I'd kill for it right now, you?"}},
{"fw_ld7_pcb_0042","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"They've got Cindy, they've got Cindy, I just saw her go down!",2,"No, no, she got away, she ran",1,"I SAW HER, she was in the lot, she-",2,"Then we can't go that way, we can't go that way, we go the other way"}},
{"fw_ld7_pcb_0043","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Why would they leave all the lights on? Every house, every single light?",2,"Because people ran out of their houses",1,"But it's like a trap, it's like a big sign saying come eat!",2,"Then turn them off on your way past, one at a time, I'll wait"}},
{"fw_ld7_pcb_0044","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is he alive? Is he still alive?",2,"I think so, he's breathing",1,"Then wake him up!",2,"If I wake him up he'll scream, and if he screams-",1,"Then he screams, WAKE HIM UP"}},
{"fw_ld7_pcb_0045","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I just kept thinking, this is how it ends, it ends next to a Piggly Wiggly cart corral",2,"It doesn't end",1,"It's a really bad place to end",2,"Then don't end there, come on, walk, one foot, then the other"}},
{"fw_ld7_pcb_0046","panic_days",3,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Somebody grab Tyler, somebody grab him, he's running!",2,"Tyler! TYLER, come back!",3,"I've got him, I've got him, I've got his shirt, hold still!",1,"Don't you EVER do that again, you hear me? EVER!"}},
{"fw_ld7_pcb_0047","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"How do you eat a can of cold chili?",2,"With a spoon, and without thinking about it",1,"It's gross",2,"It's the first thing I've eaten in a day, and it's the best thing I've ever had"}},
{"fw_ld7_pcb_0048","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is that smoke? Is that- look at the sky, it's all black over there!",2,"It's the Kroger",1,"How do you know?",2,"Because I can see the sign, the sign's burning, the red K, look"}},
{"fw_ld7_pcb_0049","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"She keeps asking where her father is",2,"What do you say?",1,"That he's at work, working late, I can't, I can't say the other thing",2,"Then say that, say it as long as you can, nobody should hurry that"}},
{"fw_ld7_pfa_0001","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Behind me! Stay there, don't step out!",2,"I can't see anything!",1,"You don't need to see. You need to stay behind me!",2,"I want to go home. Please, I want to go home, I'm scared"}},
{"fw_ld7_pfa_0002","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"I'm not leaving, I've lived here fifty years",2,"You have to come, there's no time for this!",1,"Then go without me, I'll be fine, I've got my chair and the radio",2,"The radio's all static, you know it is, come ON, I'll carry you if I have to"}},
{"fw_ld7_pfa_0003","panic_days",2,"reg=family|day=0,4|mood=angry",{1,"We stay, it's safer",2,"Safer than WHAT? Look out there!",1,"Out there's worse, here we've got locks and the guns",2,"And what do we eat? What do we drink? You think about that?"}},
{"fw_ld7_pfa_0004","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Where's your father?",2,"He went for gas",1,"That was hours ago!",2,"I know, I KNOW it was, I looked at the clock every five minutes, I can't do it anymore"}},
{"fw_ld7_pfa_0005","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"In '37 the water came up so fast we lost the cow, the house, the chickens, everything",2,"But you got out",1,"We got out with the clothes we had on and a Bible, we built it back, slow",2,"This isn't a flood, though, is it"}},
{"fw_ld7_pfa_0006","panic_days",2,"reg=family|tmp=fresh|day=0,4|mood=fear",{1,"I have to find my girlfriend, she's alone",2,"You're not going anywhere",1,"She's ALONE, she's by herself in that big house!",2,"I know, honey, and I'm sorry, and you're still not going"}},
{"fw_ld7_pfa_0007","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Eat, EAT, please eat something",2,"I can't, my stomach's in my throat",1,"Just a bite of the sandwich, one bite, I made it special",2,"...okay, one, one bite, I'm eating, look, I'm eating it"}},
{"fw_ld7_pfa_0008","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"Holy Mary, Mother of God, pray for us sinners",2,"Louder",1,"Now and at the hour of our death",2,"Again, from the start, don't stop, I'm not ready for you to stop"}},
{"fw_ld7_pfa_0009","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Cover his eyes, cover his eyes, don't let him see!",2,"He's already seen it",1,"Then don't let him see more! Cover his EYES!",2,"Come here, baby, come here, put your face in my shirt, that's it"}},
{"fw_ld7_pfa_0010","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Hush him! Hush the baby, please, please!",2,"I'm trying, he won't stop",1,"They'll hear him, they'll hear!",2,"Then take him, you do it, you're better at this than I am"}},
{"fw_ld7_pfa_0011","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Where's the dog? Where's Biscuit?",2,"Out back",1,"Bring him in, bring him in, he'll bark and bring them!",2,"I called him, he won't come, he's at the fence barking at something"}},
{"fw_ld7_pfa_0012","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"I'm too old to run",2,"You're going",1,"I'll slow you down, and the children-",2,"I'm not leaving you, and the children aren't leaving you, so stop talking about it"}},
{"fw_ld7_pfa_0013","panic_days",2,"reg=family|day=0,4|mood=grim",{1,"How many shells do we have for Dad's gun?",2,"Seven",1,"Let me hold it",2,"No, I've got it, I'm the one who knows how, I'll hold it"}},
{"fw_ld7_pfa_0014","panic_days",2,"reg=family|tmp=fresh|day=0,4|mood=sad",{1,"I left the gate open",2,"What?",1,"When we ran, I left the gate open on the farm, the cattle are out, they'll all get out",2,"Honey, the cows are the least of what's gonna get out"}},
{"fw_ld7_pfa_0015","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"Granddad offered me his pocketknife once",2,"You couldn't take that?",1,"He said he wanted somebody with a steady hand to have it",2,"I'd have been shaking too. That sort of kindness gets to you"}},
{"fw_ld7_pfa_0016","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"We're playing the quiet game",2,"Why?",1,"Because whoever's quietest wins, and the prize is a whole bag of M&Ms",2,"I'm gonna win, I'm the quietest, I'm already not talking"}},
{"fw_ld7_pfa_0017","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"I don't want to be scared anymore",2,"I know",1,"Are you scared?",2,"Yes. I wanted to keep that from you, but... yes, I'm scared"}},
{"fw_ld7_pfa_0018","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"I'm writing down all the phone numbers, in case",2,"In case of what?",1,"In case we get separated, in case somebody finds this, I'm writing everybody's number",2,"Put mine at the top, in big letters"}},
{"fw_ld7_pfa_0019","panic_days",2,"reg=family|day=0,4|mood=grim",{1,"Get the photo albums",2,"Photos? NOW?",1,"They're all we've got of her, of the whole family, we're not leaving them",2,"Fine, fine, get them, get them quick, I'll hold the bag"}},
{"fw_ld7_pfa_0020","panic_days",2,"reg=family|day=0,4|mood=angry",{1,"Remember fighting over who got the bat?",2,"You said I'd had it last time",1,"Last time was a drill",2,"And we spent the whole drill arguing. Maybe agree before we need one"}},
{"fw_ld7_pfa_0021","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Where's the medicine? Where's her heart medicine?",2,"In my purse, I think",1,"You THINK?!",2,"It's in the purse, it's in the purse, I put it in the purse, I remember putting it in the purse"}},
{"fw_ld7_pfa_0022","panic_days",2,"reg=family|day=0,4|mood=angry",{1,"Turn off the TV, turn it off, it's just the same thing over and over!",2,"I need to know what's going on",1,"It's the beep, it's just the beep!",2,"Then I'll sit here and listen to the beep, leave me be"}},
{"fw_ld7_pfa_0023","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"WHAT IS ALL THIS FUSS? WHAT'S GOING ON?",2,"Shh! Shh! Please keep your voice down!",1,"I CAN'T HEAR YOU, SPEAK UP!",2,"Oh God, somebody tell him, somebody write it down, he can't hear a word"}},
{"fw_ld7_pfa_0024","panic_days",2,"reg=family|tmp=fresh|day=0,4|mood=fear",{1,"Can you get the CB to work? Can you call somebody?",2,"I'm trying, I'm turning the knob, it's all static",1,"Say anything, say \"breaker one-nine,\" that's what they say",2,"Breaker one-nine, anybody, anybody, please, we're- I'm just a kid"}},
{"fw_ld7_pfa_0025","panic_days",2,"reg=family|day=0,4|mood=angry",{1,"Where are you off to? Come back here",2,"I just want to see",1,"See what? What could you possibly need to see?",2,"Whether they're really out there, I have to see it with my own eyes"}},
{"fw_ld7_pfa_0026","panic_days",3,"reg=family|day=0,4|mood=fear",{1,"Count off, who's here?",2,"Me",3,"Me",1,"That's three, there's supposed to be four, where's the little one?",3,"Under the bed! She's under the bed, she's been there the whole time"}},
{"fw_ld7_pfa_0027","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"I should've made us leave sooner",2,"Don't",1,"We had time, we had days, I kept saying wait, wait, wait",2,"Everyone said wait, you weren't alone, stop"}},
{"fw_ld7_pfa_0028","panic_days",2,"reg=family|tmp=fresh|day=0,4|mood=sad",{1,"Are we gonna die?",2,"No",1,"Promise?",2,"I promise, I promise, I'll do whatever it takes, I promise"}},
{"fw_ld7_pfa_0029","panic_days",2,"reg=family|day=0,4|mood=grim",{1,"I've seen worse than this",2,"You haven't",1,"I buried a husband and a son, I've seen worse",2,"Not like this, not like this, no one has"}},
{"fw_ld7_pfa_0030","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Gram used to answer everything with, have some soup",2,"Even when the world was falling apart?",1,"Said it might as well fall apart on a full stomach",2,"I'd have needed help holding the spoon. But I'd have liked hearing her say it"}},
{"fw_ld7_pfa_0031","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Push the dresser against it",2,"It's too heavy",1,"Push it, put your back into it, MOVE!",2,"It's not going, it's stuck on the rug, help me!"}},
{"fw_ld7_pfa_0032","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"Shh. Stay close to me. You don't have to talk",2,"What if they come?",1,"Then we move together. I won't leave you",2,"you promise?"}},
{"fw_ld7_pfa_0033","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"Tell me what happened to Mamaw",2,"She's resting",1,"She's not resting, she's not breathing, I saw",2,"...I'm not ready to talk about it, give me a minute, a minute, please"}},
{"fw_ld7_pfa_0034","panic_days",2,"reg=family|day=0,4|mood=fear",{1,"Why's Papaw not waking up?",2,"He's tired, he's real tired",1,"But I shook him and he didn't-",2,"Come away from there, come away, we'll let him rest, come with me"}},
{"fw_ld7_pfa_0035","panic_days",2,"reg=family|day=0,4|mood=angry",{1,"This is YOUR fault! You said it was nothing!",2,"I thought it WAS nothing, everybody said it was nothing!",1,"Everybody's not my husband! You are!",2,"Okay, okay, I know, I was wrong, scream at me, scream all you want"}},
{"fw_ld7_pfa_0036","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"What if somebody comes and we don't know they're friends?",2,"Then we'll ask",1,"And if they lie?",2,"Then they lie, and we'll know it, you can always tell when somebody's lying"}},
{"fw_ld7_pfa_0037","panic_days",2,"reg=family|day=0,4|mood=grim",{1,"Make a list of what we have",2,"Why?",1,"Because I need to see it written down, I need to see that it's not nothing",2,"Flashlight, two cans of peas, a can opener, that's it"}},
{"fw_ld7_pfa_0038","panic_days",2,"reg=family|tmp=fresh|day=0,4|mood=fear",{1,"What's wrong with the neighbors?",2,"They're sick",1,"Sick how? Like the flu?",2,"Come away from the glass, honey, we're not looking at the neighbors"}},
{"fw_ld7_pfa_0039","panic_days",2,"reg=family|day=0,4|mood=sad",{1,"Do you think the church bell still works?",2,"Why would you ask that?",1,"Because I'd like to hear it, one more time, just once",2,"I would too, I don't know if anyone's left to ring it"}},
{"fw_ld7_pla_0001","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Goddamn infection spreading everywhere, deputies, maybe you know where we should go?",2,"Wish I did, I'm getting the same hiss on the radio that you are",1,"Then what are you even FOR?",2,"Right now I'm for standing here so you've got somebody to yell at"}},
{"fw_ld7_pla_0002","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|tmp=fresh|day=0,4|mood=fear",{1,"I remember a woman asking me to help. Said there were three in her yard",2,"Did she tell you which house?",1,"Yellow, with a swing. Her kids were there, she said. Couldn't get the words out",2,"I wouldn't promise help I didn't have. Saying sorry can feel like saying nothing"}},
{"fw_ld7_pla_0003","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Why isn't anybody DOING something? You're the police!",2,"I've been doing something since four in the morning, I just can't tell you what it's done",1,"That's not an answer!",2,"It's the only one I've got, and I've been saving it all day"}},
{"fw_ld7_pla_0004","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Folks, get inside, everybody inside, now",2,"We ARE inside, we've been inside for two days",1,"Then stay inside, don't open it for anybody, you hear me, not even me",2,"What does that mean, not even you?"}},
{"fw_ld7_pla_0005","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=fear",{1,"Is the sheriff coming? Somebody said the sheriff was coming",2,"The sheriff went to Louisville and didn't come back",1,"Did he call?",2,"Nobody's called, nobody calls anymore"}},
{"fw_ld7_pla_0006","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=sad",{1,"Are they dead? Are those things dead? You shot one, I saw you",2,"I put four in his chest and he kept coming, so I honestly don't know what dead means anymore",1,"Oh God",2,"Head, ma'am, it's the only thing I've seen work, and I wish I'd never found that out"}},
{"fw_ld7_pla_0007","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"I once begged a cop to look at my bitten husband in our van",2,"What did he tell you?",1,"I kept saying he must have a first aid kit. Like saying it would fix everything",2,"A uniform doesn't mean somebody has a kit, or that a kit can fix a bite. I'm sorry you had to ask"}},
{"fw_ld7_pla_0008","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Anybody here bitten? Anybody scratched? Don't lie to me, I'm not gonna shoot you, I just need to know",2,"No, nobody, we've been inside",1,"Roll up your sleeves, all of you, slow",2,"Nobody's hurt, see? SEE?"}},
{"fw_ld7_pla_0009","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=angry",{1,"Is it true the Army's coming? My neighbor said the Army's coming",2,"Ask me tomorrow, I'll know less than I do now",1,"Don't joke about it!",2,"I'm not joking, I stopped being able to joke around lunchtime"}},
{"fw_ld7_pla_0010","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Where do we sleep? Where's anybody sleeping?",2,"The Baptist church on the corner's got room, some of the deputies' families are there",1,"Is it safe?",2,"It's got four walls and some men with guns, that's about as safe as it gets right now"}},
{"fw_ld7_pla_0011","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=sad",{1,"Ever have somebody beg you for a ride for their children?",2,"More than once. Couldn't promise a seat I didn't have",1,"They tell you how little the kids are, how quiet they'll be",2,"Makes you want to say yes before thinking. But wanting room doesn't make room"}},
{"fw_ld7_pla_0012","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=grim",{1,"If I found a gun, would I have to hand it over?",2,"I'd want you to learn to handle it safely before carrying it",1,"I never shot anything but cans",2,"Then don't pretend otherwise. That's a better start than showing off"}},
{"fw_ld7_pla_0013","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"Is the bridge open? We're trying to get across to Indiana",2,"No",1,"Just no?",2,"There's a National Guard line across it and a lot of people sitting in front of it, that's all I know"}},
{"fw_ld7_pla_0014","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I need you to show me the neighbor",2,"I'm not going back there, I'm NOT, he's one of them now",1,"Then just point, I'll go",2,"Third one on the left, the one with the red shutters, don't go in without- just don't, please"}},
{"fw_ld7_pla_0015","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Somebody said the police are leaving town",2,"Not me",1,"But you could, couldn't you? You could just go?",2,"I could, and I've thought about it twice today, so I wouldn't ask me that again"}},
{"fw_ld7_pla_0016","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Deputy, are you scared?",2,"Terrified, I wet myself an hour ago and nobody's the wiser",1,"...why would you tell me that?",2,"Because you looked like you needed company"}},
{"fw_ld7_pla_0017","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=grim",{1,"What number do we call? Is there a number?",2,"There was a number, it's 911, I'm the 911 now",1,"But who's gonna answer if you're out here?",2,"Nobody, ma'am, nobody's gonna answer, that's the problem with being the 911"}},
{"fw_ld7_pla_0018","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=calm",{1,"I was a medic in the Guard, I can help, I can do something",2,"You any good?",1,"Eight years, two tours of nothing, I'm real good",2,"Then come with me, I've got a man bleeding behind the pharmacy"}},
{"fw_ld7_pla_0019","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=fear",{1,"The radio on your shoulder, what did it say? It just made noise, what did they say?",2,"They said stand by",1,"Stand by for what?",2,"They said stand by, that's the entire message, it's been the entire message all day"}},
{"fw_ld7_pla_0020","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Is there a curfew? Somebody put a flyer on a pole, it says curfew",2,"Not from my office, I haven't seen it",1,"Then who put it up?",2,"Whoever's still giving orders, I'd stay in, it's not worth finding out"}},
{"fw_ld7_pla_0021","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Where's the National Guard? The armory's got a light on, but nobody answers",2,"Armory's empty, they left before noon",1,"Left where?",2,"North, with everything they could carry, and they didn't tell me either"}},
{"fw_ld7_pla_0022","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"The radio says it's rabies, is it rabies? Please say it's rabies",2,"Rabies doesn't do that",1,"Then what is it?",2,"...I don't know, and neither does anyone I've talked to"}},
{"fw_ld7_pla_0023","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"How long since you slept?",2,"I don't know, since before the sirens",1,"Go lie down somewhere, I'll take the front",2,"I can't, the Dolan boy's face is just there every time I do"}},
{"fw_ld7_pla_0024","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"Have you seen my mother? She's seventy-four, she's got a blue coat, she walks with a cane",2,"Where was she last?",1,"Her house on Elm, she wouldn't answer the phone, I couldn't get through, nobody can get through",2,"I'll look if I go past, I can't promise, I'm sorry, I can't promise a thing"}},
{"fw_ld7_pla_0025","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"I got a question and I want a straight answer, is it safe to stay here?",2,"No",1,"...that's it? No?",2,"You wanted a straight answer, I gave you a straight one, I don't know a place that IS safe"}},
{"fw_ld7_pla_0026","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Keep your voice down!",2,"I'm sorry, I'm sorry, I can't, I can't stop shaking",1,"I know, I'm shaking too, but you hear that dragging sound? Quiet, they're close",2,"Okay, okay, I'm not breathing, I'm not breathing"}},
{"fw_ld7_pla_0027","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=grim",{1,"How many of them are there?",2,"More than I've got bullets for, and that's all I'm gonna say",1,"Is that supposed to calm me down?",2,"Nothing's supposed to calm you down, that's the honest part"}},
{"fw_ld7_pla_0028","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"Please tell me it's gonna stop, please, just tell me it's gonna stop",2,"I can't tell you that",1,"LIE to me then! Lie to me, I'm begging!",2,"...it's gonna stop, it's gonna stop, okay? It's gonna stop"}},
{"fw_ld7_pla_0029","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=angry",{1,"You left us! Yesterday you drove right past and you didn't stop!",2,"I had a man in the back seat, I couldn't, I wanted to",1,"We banged on your hood! We BANGED on it!",2,"I heard you, I heard every bit of it, I'll hear it a while"}},
{"fw_ld7_pla_0030","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is there anybody else in the house, any kids, anybody sick?",2,"My mother, she's in the back room, she's got a fever",1,"How long's the fever?",2,"Since last night, I put a wet rag on her, she isn't answering me",1,"Stay right here, behind me, don't go in there"}},
{"fw_ld7_pla_0031","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"What do I tell my kids?",2,"What do they know?",1,"They saw Mr. Pruitt, they saw what he did to the dog",2,"Tell them it's a sickness, tell them the sick people are sick, I don't know what else to give you"}},
{"fw_ld7_pla_0032","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=angry",{1,"Somebody's looting the hardware store and you're just standing here?!",2,"There's a hundred of them in there and one of me",1,"So we just let them?",2,"You want to walk in there and tell them no, go ahead, I'll cover you from here"}},
{"fw_ld7_pla_0033","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=grim",{1,"Can you shoot them from a distance? Can you pick them off?",2,"I'd run out of ammo before I ran out of them",1,"So what, we wait?",2,"I've been waiting since the radio quit, ma'am, and nothing's changed but the number"}},
{"fw_ld7_pla_0034","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Somebody on the CB says Louisville's gone",2,"Gone how?",1,"Just gone, burned, nobody left, that's what he said",2,"People on the CB say a lot of things, don't repeat that to anybody else"}},
{"fw_ld7_pla_0035","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"You folks heading to the school?",2,"That's what we heard, is it still open?",1,"They haven't closed it. There's so many sick people in that gym, it's not working",2,"Then why are you sending us there?",1,"I'm telling you what's there, not telling you to go. I can't tell you where else to go"}},
{"fw_ld7_pla_0036","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"My boy's fourteen, red jacket, about this tall, he was riding his bike when the sirens started",2,"Name?",1,"Cody, Cody Sipes, please, if you see him, tell him to go home",2,"Cody Sipes, red jacket, I'll tell every person I meet"}},
{"fw_ld7_pla_0037","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Do we shoot them?",2,"Do you see anybody who isn't walking right, with a vacant look?",1,"There's one by the Dairy Bar",2,"Then don't go near that one, don't shoot unless you've got no other choice, bullets bring more"}},
{"fw_ld7_pla_0038","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=angry",{1,"Every other word out of your mouth is \"I don't know\"!",2,"Because I DON'T know! You think I'd keep it from you?",1,"I'd rather you made something up!",2,"I know you would, so would I, I'm sorry, I can't"}},
{"fw_ld7_pla_0039","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"What about the hospital?",2,"Don't go there",1,"My mother-in-law needs dialysis!",2,"There's no dialysis, there's no doctors, the whole place is just... don't go, I'm telling you as a favor"}},
{"fw_ld7_pla_0040","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=calm",{1,"You look dead on your feet, Officer, can I get you some water?",2,"...I'd take that, thank you",1,"Sit down a second, nobody's gonna bite",2,"Careful what you say about that, ma'am, I don't have a sense of humor left"}},
{"fw_ld7_pla_0041","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Lock up, put something heavy against it, and keep the lights off",2,"For how long?",1,"Until somebody tells you different",2,"Who's gonna tell us different? Who's left to tell us?"}},
{"fw_ld7_pla_0042","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"Does anybody know what this IS?",2,"A guy at the state lab on the phone said maybe a chemical, maybe a disease, and then the line went dead",1,"A guy?",2,"A guy, I never got his name, I've been thinking about him all day, he sounded like he was crying"}},
{"fw_ld7_pla_0043","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|tmp=fresh|day=0,4|mood=fear",{1,"Don't leave us here, don't go, you're all we've got",2,"I have to check the next block",1,"What if they come while you're gone?",2,"Then you run, you run to the church and you don't stop, you hear me, you don't stop"}},
{"fw_ld7_pla_0044","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=angry",{1,"My taxes pay your salary!",2,"I haven't been paid in nine days",1,"Well- well, that's not my fault!",2,"I know it isn't, ma'am, I'm just telling you why I'm not as helpful as I'd like"}},
{"fw_ld7_pla_0045","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Have you got a ride? Something that runs, with gas in it?",2,"Half a tank",1,"I need to get five people to the school and I've got no ride",2,"Get in, I'll drive, hurry, tell them to hurry"}},
{"fw_ld7_pla_0046","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"My husband's a deputy too, have you seen him? Hollis, Hollis Gaines, tall, red hair",2,"Hollis was on the north end the last I heard",1,"When was that?",2,"Before the radio quit, I'm sorry, that's the last I've got"}},
{"fw_ld7_pla_0047","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Is it safe to burn them? To burn the bodies?",2,"I wouldn't, not yet",1,"There's one in our front yard that won't stay down!",2,"Then it's not a body, it's one of THEM, you're gonna need to make a different call"}},
{"fw_ld7_pla_0048","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Did you see which way it went?",2,"Toward the tracks, I think, I didn't look, I was running",1,"How many?",2,"I don't know, I don't know, five? Six? It was loud, I wasn't counting"}},
{"fw_ld7_pla_0049","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=angry",{1,"They said on the radio we should follow instructions, whose instructions? Where are they?",2,"I haven't gotten any either",1,"Then why's the radio saying it?",2,"Because somebody recorded it a long time ago and it's looping, ma'am, nobody's home"}},
{"fw_ld7_pla_0050","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=fear",{1,"I once watched my neighbor stand in his garage for an hour. Thought he'd turned",2,"Had he said anything?",1,"Kept turning his head, like he was listening to something",2,"You couldn't know from that alone. I'd keep my distance, but I wouldn't call it proof"}},
{"fw_ld7_pla_0051","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Where's your family?",2,"Last I knew, my wife was at her sister's and the kids were at the pool. I was at work",1,"Do you remember the address?",2,"Just out past the Methodist church. I never needed the number before, and now it's all I can think about"}},
{"fw_ld7_pla_0052","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=grim",{1,"Y'all keep saying head, aim for the head",2,"It's what's working",1,"You ever say \"it's what's working\" about anything else in your life?",2,"Yeah, my first marriage, but that's a different story"}},
{"fw_ld7_pla_0053","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=fear",{1,"Just tell me where the safest place is, even if it's a lie",2,"The Methodist church, they've got good locks and a priest with a shotgun",1,"It's a pastor, not a priest",2,"Ma'am, I'm in no position to ask for credentials"}},
{"fw_ld7_pla_0054","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=sad",{1,"Is it true they're not people anymore?",2,"I don't want to say",1,"Please, I need to know if it's okay to-",2,"Don't hesitate, ma'am, that's all I'll say, don't hesitate"}},
{"fw_ld7_pla_0055","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"They went past us, the Army convoy, and they didn't even slow down, why didn't they stop?",2,"They had orders, I'd guess",1,"To drive past us?",2,"To go somewhere, and we aren't there, that's what I figure"}},
{"fw_ld7_pla_0056","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Get away from the corner, get OFF the corner!",2,"What's wrong? What's coming?",1,"Nothing yet, but it's open and you can see all the way down, now MOVE",2,"Okay, okay, I'm moving, I'm moving!"}},
{"fw_ld7_pla_0057","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"What do I do with the dead? Do I bury Gerald? He's in the bed, he's, he's just gone",2,"Did he turn?",1,"I don't know, he stopped and then I came out, I can't go back in there",2,"Lock it from the outside, don't go in, I'll do what I can when I get a minute"}},
{"fw_ld7_pla_0058","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"Do you have any idea how long this lasts?",2,"You mean the sirens, the quiet, or the whole thing?",1,"The whole thing!",2,"Longer than I can plan for, which is why I've quit planning past lunch"}},
{"fw_ld7_pla_0059","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"Take us to the fort, they've got soldiers, they've got big gates!",2,"The fort's shooting people who walk up to the gate",1,"Who told you that?!",2,"A man who walked up to the gate, he got back with a hole in his hat"}},
{"fw_ld7_pla_0060","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|tmp=fresh|day=0,4|mood=fear",{1,"Is it in the air? Is it the air? Tell me if it's the air!",2,"I don't know",1,"Should I wear something? A rag, a towel, something over my face?",2,"Tie something on if it makes you feel better, I've got a bandana, here"}},
{"fw_ld7_pla_0061","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=fear",{1,"My little girl's got a fever, is that it? Is she infected?",2,"A fever's a fever, is there a bite on her?",1,"No, no, I checked, I checked her whole body twice!",2,"Then keep her cool and keep checking, I wish I had a doctor to send you"}},
{"fw_ld7_pla_0062","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"I keep remembering a bitten man they tied up in a garage",2,"Was he conscious?",1,"Talking, but not to any of us. Wouldn't look at us",2,"That's not something you forget. I hope nobody took a risk trying to handle him alone"}},
{"fw_ld7_pla_0063","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=calm",{1,"Would you take a pistol from somebody who was scared to use it?",2,"I'd ask why they wanted to give it up",1,"I've never fired one at a person",2,"I'm glad you'd hesitate. But carrying it or handing it over ought to be a real decision, not panic"}},
{"fw_ld7_pla_0064","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=angry",{1,"Somebody said you shot Mr. Dolan",2,"It wasn't Mr. Dolan anymore",1,"He had a WIFE!",2,"She's the one who asked me to, ma'am, I'd appreciate it if you'd keep that to yourself"}},
{"fw_ld7_pla_0065","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"My mother's in the brick house at the end of Ash, she's eighty, she can't walk without help",2,"Say it again, slower",1,"Ash Lane, the brick one, there's a ramp, she's got a ramp",2,"Ash, brick, ramp, okay, got it written on my hand, I'll go if I can"}},
{"fw_ld7_pla_0066","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=fear",{1,"Where's the rescue squad? I've been calling for hours!",2,"They quit answering",1,"Quit? They CAN'T quit! That's their JOB!",2,"I know it's their job, ma'am, I'm trying to tell you the squad isn't coming, none of them are"}},
{"fw_ld7_pla_0067","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=grim",{1,"Can we light a fire? We're freezing and- well, it's July, we're just scared",2,"Don't, smoke brings them in",1,"How do you know?",2,"Because that's how the Pruitt place went, I watched it happen"}},
{"fw_ld7_pla_0068","panic_days",3,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=civilian,family,worker,rescue|r3=law,swat|day=0,4|mood=angry",{1,"He's a cop, he'll protect us",2,"He's one cop, he's got one gun, and he's leaving",3,"I'm going to the school, I'm not leaving you, I'm just not staying here",1,"That's leaving!",3,"Then call it leaving, I'm still going"}},
{"fw_ld7_pla_0069","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"You folks from Radcliff? Anybody know where the nearest Army post is?",2,"Fort Knox",1,"That's the one I mean, how do I get there?",2,"Hell, you're a cop, you tell US"}},
{"fw_ld7_pla_0070","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=f|day=0,4|mood=funny",{1,"I'd like to report a crime, somebody stole my riding mower",2,"A mower",1,"A John Deere, it was in the shed, I saw 'em driving it down the hill",2,"Hahaha- sorry, sorry, ma'am, I'll put it on the list, it's right under \"end of the world\""}},
{"fw_ld7_pla_0071","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|x1=f|day=0,4|mood=fear",{1,"I won't loot, I won't take anything, I promise, I PROMISE",2,"Nobody's accusing you",1,"I'm scared of needing food for my kids and having nothing to offer for it",2,"Then ask before you take anything. I can't promise what another person will spare"}},
{"fw_ld7_pla_0072","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=law,swat|r2=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Everybody who came with the group, count heads right now",2,"Seven",1,"Seven? I saw nine",2,"Two went back for something, I told them not to, I told them!"}},
{"fw_ld7_pla_0073","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|day=0,4|mood=sad",{1,"The TV said everybody should go to the fairgrounds",2,"Nobody's at the fairgrounds, I've been there",1,"Then who put it on the TV?",2,"Somebody who wasn't there, that's all I can tell you"}},
{"fw_ld7_pla_0074","panic_days",2,"reg=civilian,family,worker,rescue,law|r1=civilian,family,worker,rescue|r2=law|day=0,4|mood=sad",{1,"You stayed, you could've gone and you stayed",2,"I'm not staying, I just can't think of where else to go",1,"That's more honest than anything I've heard today",2,"It's the only thing I've got left to give you"}},
{"fw_ld7_pla_0075","panic_days",2,"reg=civilian,family,worker,rescue,law,swat|r1=civilian,family,worker,rescue|r2=law,swat|x1=m|day=0,4|mood=grim",{1,"I'm a Vietnam vet, I'm not going out like this",2,"Out like what?",1,"Hiding under a bed, I did enough of that in '69",2,"I'd rather find somewhere you could rest, sir. Somewhere we've actually checked"}},
}
